import { useEffect, useRef, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { publicKeys } from "@/config/public-keys";
import { apiFetch } from "@/lib/api";
import { normalizeApiError, readResponseBody } from "@/lib/api-error";
import { API_BASE_URL } from "@/lib/api-base";
import { authClient, clearAuthToken, getAuthToken, syncAuthTokenFromResult } from "@/lib/auth";

const GOOGLE_CLIENT_ID = publicKeys.googleClientId;

type ApiState = {
  status: "idle" | "loading" | "success" | "error";
  code?: number;
  body?: unknown;
};

type AuthState = {
  token: string;
  user?: unknown;
};

const initialState: ApiState = { status: "idle" };

type AuthConfig = {
  socialProviders: string[];
};

function normalizeAuthResult(result: unknown): ApiState {
  const response = result as {
    data?: {
      token?: string | null;
      user?: unknown;
      redirect?: boolean;
      url?: string;
    } | null;
    error?: {
      status?: number;
      message?: string;
      code?: string;
    } | null;
  };

  if (response.error) {
    return {
      status: "error",
      code: response.error.status,
      body: {
        ok: false,
        error: normalizeApiError(response.error)
      }
    };
  }

  return {
    status: "success",
    code: 200,
    body: {
      ok: true,
      data: response.data ?? null
    }
  };
}

async function callApi(path: string, init?: Parameters<typeof apiFetch>[1]): Promise<ApiState> {
  try {
    const response = await apiFetch(path, init);
    const body = await readResponseBody(response);

    return {
      status: response.ok ? "success" : "error",
      code: response.status,
      body
    };
  } catch (error) {
    return {
      status: "error",
      body: {
        ok: false,
        error: normalizeApiError(error)
      }
    };
  }
}

function applyTokenFromResult(result: ApiState, setAuth: (auth: AuthState) => void) {
  if (result.status !== "success" || !result.body || typeof result.body !== "object" || !("data" in result.body)) {
    return;
  }

  const nextAuth = syncAuthTokenFromResult(result.body as Parameters<typeof syncAuthTokenFromResult>[0]);

  if (nextAuth.token) {
    setAuth(nextAuth);
  }
}

function ResultPanel({ title, result }: { title: string; result: ApiState }) {
  const variant = result.status === "success" ? "default" : result.status === "error" ? "destructive" : "secondary";

  return (
    <div className="rounded-md border border-border bg-muted/30 p-4 text-left">
      <div className="mb-3 flex items-center justify-between gap-3">
        <h2 className="text-sm font-medium text-foreground">{title}</h2>
        <Badge variant={variant}>{result.code ?? result.status}</Badge>
      </div>
      <pre className="max-h-64 overflow-auto rounded bg-background p-3 text-xs text-muted-foreground">
        {result.status === "idle" ? "Click a request button to run this check." : JSON.stringify(result.body, null, 2)}
      </pre>
    </div>
  );
}

function loadGoogleIdentityServices(): Promise<void> {
  if (window.google?.accounts?.id) {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const existingScript = document.querySelector<HTMLScriptElement>('script[src="https://accounts.google.com/gsi/client"]');

    if (existingScript) {
      existingScript.addEventListener("load", () => resolve(), { once: true });
      existingScript.addEventListener("error", () => reject(new Error("Google Identity Services failed to load")), {
        once: true
      });
      return;
    }

    const script = document.createElement("script");
    script.src = "https://accounts.google.com/gsi/client";
    script.async = true;
    script.defer = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error("Google Identity Services failed to load"));
    document.head.appendChild(script);
  });
}

const ExamplesPage = () => {
  const [health, setHealth] = useState<ApiState>(initialState);
  const [withoutToken, setWithoutToken] = useState<ApiState>(initialState);
  const [withToken, setWithToken] = useState<ApiState>(initialState);
  const [authResult, setAuthResult] = useState<ApiState>(initialState);
  const [auth, setAuth] = useState<AuthState>({ token: getAuthToken() });
  const [activeAuthTab, setActiveAuthTab] = useState("username");
  const googleButtonRef = useRef<HTMLDivElement | null>(null);
  const [googleButtonHost, setGoogleButtonHost] = useState<HTMLDivElement | null>(null);
  const [googleButtonState, setGoogleButtonState] = useState<"idle" | "loading" | "ready" | "error">("idle");
  const [authConfig, setAuthConfig] = useState<AuthConfig>({ socialProviders: [] });
  const [username, setUsername] = useState("demo_user");
  const [email, setEmail] = useState("demo@example.com");
  const [password, setPassword] = useState("password123");

  const runHealth = async () => {
    setHealth({ status: "loading" });
    setHealth(await callApi("/health"));
  };

  const runWithoutToken = async () => {
    setWithoutToken({ status: "loading" });
    setWithoutToken(await callApi("/todos", { auth: false }));
  };

  const runWithToken = async () => {
    setWithToken({ status: "loading" });
    setWithToken(await callApi("/todos"));
  };

  const applyAuthResult = (result: ApiState) => {
    setAuthResult(result);
    applyTokenFromResult(result, setAuth);
  };

  const runSignUp = async () => {
    setAuthResult({ status: "loading" });
    applyAuthResult(
      normalizeAuthResult(
        await authClient.signUp.email({
          name: username,
          email,
          password,
          username,
          displayUsername: username
        })
      )
    );
  };

  const runUsernameSignUp = runSignUp;

  const runUsernameSignIn = async () => {
    setAuthResult({ status: "loading" });
    applyAuthResult(
      normalizeAuthResult(
        await authClient.signIn.username({
          username,
          password,
          rememberMe: true
        })
      )
    );
  };

  const runEmailSignIn = async () => {
    setAuthResult({ status: "loading" });
    applyAuthResult(
      normalizeAuthResult(
        await authClient.signIn.email({
          email,
          password,
          rememberMe: true
        })
      )
    );
  };

  const runSignOut = async () => {
    setAuthResult({ status: "loading" });
    const result = normalizeAuthResult(await authClient.signOut());
    clearAuthToken();
    setAuth({ token: "" });
    setAuthResult(result);
  };

  useEffect(() => {
    void callApi("/auth-config", { auth: false }).then((result) => {
      if (result.status !== "success" || !result.body || typeof result.body !== "object" || !("data" in result.body)) {
        return;
      }

      setAuthConfig((result.body as { data: AuthConfig }).data);
    });
  }, []);

  useEffect(() => {
    const clientId = GOOGLE_CLIENT_ID.trim();
    const googleEnabled = authConfig.socialProviders.includes("google");

    if (activeAuthTab !== "google" || !clientId || !googleEnabled || !googleButtonHost) {
      return;
    }

    let cancelled = false;
    setGoogleButtonState("loading");

    void loadGoogleIdentityServices()
      .then(() => {
        if (cancelled) {
          return;
        }

        const googleIdentity = window.google?.accounts?.id;

        if (!googleIdentity) {
          throw new Error("Google Identity Services is unavailable");
        }

        googleButtonHost.innerHTML = "";
        googleIdentity.initialize({
          client_id: clientId,
          callback: async (response) => {
            setAuthResult({ status: "loading" });
            applyAuthResult(
              normalizeAuthResult(
                await authClient.signIn.social({
                  provider: "google",
                  idToken: {
                    token: response.credential
                  }
                })
              )
            );
          }
        });
        googleIdentity.renderButton(googleButtonHost, {
          theme: "outline",
          size: "large",
          width: 260
        });
        setGoogleButtonState("ready");
        setAuthResult({
          status: "success",
          code: 200,
          body: {
            ok: true,
            data: {
              provider: "google",
              state: "button-rendered",
              clientIdPreview: `${clientId.slice(0, 12)}...`
            }
          }
        });
      })
      .catch((error) => {
        setGoogleButtonState("error");
        setAuthResult({
          status: "error",
          body: {
            ok: false,
            error: {
              code: "GOOGLE_IDENTITY_SERVICES_LOAD_FAILED",
              message: error instanceof Error ? error.message : "Google Identity Services failed to load"
            }
          }
        });
      });

    return () => {
      cancelled = true;
    };
  }, [activeAuthTab, authConfig.socialProviders, googleButtonHost]);

  return (
    <div className="min-h-screen bg-background px-6 py-10">
      <Card className="mx-auto max-w-5xl">
        <CardHeader>
          <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <CardTitle>Selfhost API Demo</CardTitle>
              <CardDescription>Selfhost auth/API example route. Backend base URL: {API_BASE_URL}</CardDescription>
            </div>
            <Badge variant="outline">Example</Badge>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          <Tabs value={activeAuthTab} onValueChange={setActiveAuthTab} className="space-y-4">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="username">Username</TabsTrigger>
              <TabsTrigger value="email">Email</TabsTrigger>
              <TabsTrigger value="google">Google</TabsTrigger>
            </TabsList>

            <TabsContent value="username" className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="auth-username">Username</Label>
                  <Input id="auth-username" value={username} onChange={(event) => setUsername(event.target.value)} />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="auth-username-password">Password</Label>
                  <Input
                    id="auth-username-password"
                    type="password"
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                  />
                </div>
              </div>
              <div className="flex flex-col gap-3 sm:flex-row">
                <Button onClick={runUsernameSignUp}>Register</Button>
                <Button variant="secondary" onClick={runUsernameSignIn}>
                  Sign in
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="email" className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="auth-email">Email</Label>
                  <Input id="auth-email" value={email} onChange={(event) => setEmail(event.target.value)} />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="auth-email-password">Password</Label>
                  <Input
                    id="auth-email-password"
                    type="password"
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                  />
                </div>
              </div>
              <div className="flex flex-col gap-3 sm:flex-row">
                <Button onClick={runSignUp}>Register</Button>
                <Button variant="secondary" onClick={runEmailSignIn}>
                  Sign in
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="google" className="space-y-4">
              <div className="min-h-20 rounded-md border border-border bg-muted/30 p-4">
                {GOOGLE_CLIENT_ID && authConfig.socialProviders.includes("google") ? (
                  <div className="space-y-3">
                    {googleButtonState === "loading" ? (
                      <div className="text-sm text-muted-foreground">Loading Google login...</div>
                    ) : null}
                    {googleButtonState === "error" ? (
                      <div className="text-sm text-destructive">Google login failed to load.</div>
                    ) : null}
                    <div
                      ref={(node) => {
                        googleButtonRef.current = node;
                        setGoogleButtonHost(node);
                      }}
                    />
                  </div>
                ) : (
                  <div className="text-sm text-muted-foreground">
                    Set VITE_GOOGLE_CLIENT_ID and backend GOOGLE_CLIENT_SECRET to render Google login.
                  </div>
                )}
              </div>
            </TabsContent>
          </Tabs>

          <ResultPanel title="Better Auth result" result={authResult} />

          <div className="grid gap-3 sm:grid-cols-3">
            <Button onClick={runHealth}>Check health</Button>
            <Button variant="secondary" onClick={runWithoutToken}>
              Protected without token
            </Button>
            <Button onClick={runWithToken}>Protected with current token</Button>
          </div>

          <div className="flex">
            <Button variant="outline" onClick={runSignOut}>
              Sign out
            </Button>
          </div>

          <div className="grid gap-4 lg:grid-cols-3">
            <ResultPanel title="GET /api/health" result={health} />
            <ResultPanel title="GET /api/todos" result={withoutToken} />
            <ResultPanel title="GET /api/todos + Bearer" result={withToken} />
          </div>

          <div className="rounded-md border border-border bg-muted/30 p-4 text-xs text-muted-foreground">
            Current bearer token: <span className="font-mono text-foreground">{auth.token || "(empty)"}</span>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default ExamplesPage;
